// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ImproveWriting Mejora la redacción de un borrador.
	// (POST /api/v1/admin/assistant/improve-writing)
	ImproveWriting(ctx context.Context, request ImproveWritingRequestObject) (ImproveWritingResponseObject, error)
	// SuggestCover Sugiere la idea de la portada de un borrador.
	// (POST /api/v1/admin/assistant/suggest-cover)
	SuggestCover(ctx context.Context, request SuggestCoverRequestObject) (SuggestCoverResponseObject, error)
	// SuggestMetadata Sugiere título, extracto y etiquetas para un borrador.
	// (POST /api/v1/admin/assistant/suggest-metadata)
	SuggestMetadata(ctx context.Context, request SuggestMetadataRequestObject) (SuggestMetadataResponseObject, error)
	// ListComments Lista los comentarios para moderar.
	// (GET /api/v1/admin/comments)
	ListComments(ctx context.Context, request ListCommentsRequestObject) (ListCommentsResponseObject, error)
	// AnalyzeComment Pide de nuevo el análisis de un comentario.
	// (POST /api/v1/admin/comments/{id}/analyze)
	AnalyzeComment(ctx context.Context, request AnalyzeCommentRequestObject) (AnalyzeCommentResponseObject, error)
	// ApproveComment Aprueba un comentario.
	// (POST /api/v1/admin/comments/{id}/approve)
	ApproveComment(ctx context.Context, request ApproveCommentRequestObject) (ApproveCommentResponseObject, error)
	// RejectComment Rechaza un comentario.
	// (POST /api/v1/admin/comments/{id}/reject)
	RejectComment(ctx context.Context, request RejectCommentRequestObject) (RejectCommentResponseObject, error)
	// ReplyToComment Responde a un comentario como autor.
	// (POST /api/v1/admin/comments/{id}/replies)
	ReplyToComment(ctx context.Context, request ReplyToCommentRequestObject) (ReplyToCommentResponseObject, error)
	// ListCVVersions Lista las versiones del CV.
	// (GET /api/v1/admin/cv)
	ListCVVersions(ctx context.Context, request ListCVVersionsRequestObject) (ListCVVersionsResponseObject, error)
	// SetCurrentCV Marca una versión del CV como la vigente.
	// (POST /api/v1/admin/cv/versions/{id}/current)
	SetCurrentCV(ctx context.Context, request SetCurrentCVRequestObject) (SetCurrentCVResponseObject, error)
	// UploadCV Sube una versión del CV en PDF.
	// (POST /api/v1/admin/cv/{language})
	UploadCV(ctx context.Context, request UploadCVRequestObject) (UploadCVResponseObject, error)
	// ListPosts Lista los posts en cualquier estado.
	// (GET /api/v1/admin/posts)
	ListPosts(ctx context.Context, request ListPostsRequestObject) (ListPostsResponseObject, error)
	// CreatePost Crea un post.
	// (POST /api/v1/admin/posts)
	CreatePost(ctx context.Context, request CreatePostRequestObject) (CreatePostResponseObject, error)
	// DeletePost Archiva un post.
	// (DELETE /api/v1/admin/posts/{id})
	DeletePost(ctx context.Context, request DeletePostRequestObject) (DeletePostResponseObject, error)
	// GetPost Devuelve un post en cualquier estado.
	// (GET /api/v1/admin/posts/{id})
	GetPost(ctx context.Context, request GetPostRequestObject) (GetPostResponseObject, error)
	// UpdatePost Reemplaza los datos editables de un post.
	// (PUT /api/v1/admin/posts/{id})
	UpdatePost(ctx context.Context, request UpdatePostRequestObject) (UpdatePostResponseObject, error)
	// Login Inicia sesión y emite las cookies de acceso y refresco.
	// (POST /api/v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoca el token de refresco, si llega, y borra las cookies.
	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetCurrentUser Devuelve el usuario de la sesión actual.
	// (GET /api/v1/auth/me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// RefreshSession Rota el token de refresco y emite cookies nuevas.
	// (POST /api/v1/auth/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// GetCurrentCV Devuelve el CV en PDF vigente de cada idioma.
	// (GET /api/v1/cv)
	GetCurrentCV(ctx context.Context, request GetCurrentCVRequestObject) (GetCurrentCVResponseObject, error)
	// ListPublishedPosts Lista los posts publicados.
	// (GET /api/v1/posts)
	ListPublishedPosts(ctx context.Context, request ListPublishedPostsRequestObject) (ListPublishedPostsResponseObject, error)
	// GetPublishedPost Devuelve un post publicado por su slug.
	// (GET /api/v1/posts/{slug})
	GetPublishedPost(ctx context.Context, request GetPublishedPostRequestObject) (GetPublishedPostResponseObject, error)
	// ListPostComments Lista los comentarios aprobados de un post.
	// (GET /api/v1/posts/{slug}/comments)
	ListPostComments(ctx context.Context, request ListPostCommentsRequestObject) (ListPostCommentsResponseObject, error)
	// SubmitComment Envía un comentario anónimo a un post publicado.
	// (POST /api/v1/posts/{slug}/comments)
	SubmitComment(ctx context.Context, request SubmitCommentRequestObject) (SubmitCommentResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

